    # Main method that dispatches to the appropriate quarter-circle method
    @staticmethod
    def checkReachability(direction):

        if direction == Direction.NORTH:
            Reachability.checkReachabilityN()

        elif direction == Direction.EAST:
            Reachability.checkReachabilityE()

        elif direction == Direction.SOUTH:
            Reachability.checkReachabilityS()

        elif direction == Direction.WEST:
            Reachability.checkReachabilityW()

        elif direction == Direction.NORTHEAST:
            Reachability.checkReachabilityNE()

        elif direction == Direction.SOUTHEAST:
            Reachability.checkReachabilitySE()

        elif direction == Direction.NORTHWEST:
            Reachability.checkReachabilityNW()

        elif direction == Direction.SOUTHWEST:
            Reachability.checkReachabilitySW()
        else:
            raise ValueError("Invalid direction: " + str(direction))
